import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.rtg.rtg.genericrtg import GenericRtg

__author__ = 'Michal Ernst, Dawid Gwizdz, Marcin Usielski'
__copyright__ = 'Copyright (C) 2019-2023, Nokia'
__email__ = 'michal.ernst@nokia.com, dawid.gwizdz@nokia.com, marcin.usielski@nokia.com'


class Start(GenericRtg):
    """Start command class."""

    def __init__(self, connection, scenario=None, duration=None, queue=None, prompt=None, newline_chars=None,
                 runner=None):
        """
        Start command.

        :param connection: moler connection to device, terminal when command is executed.
        :param scenario: scenario to start
        :param duration: time which scenario will be run
        :param queue: queue to add execution scenario
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Start, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.scenario = scenario
        self.duration = duration
        self.queue = queue

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "start"

        if self.scenario:
            cmd = f"{cmd} {self.scenario}"

        if self.duration:
            if self._regex_helper.search(r'\S+\s+\S+', str(self.duration)):
                cmd = f"{cmd} {self.duration}"
            else:
                cmd = f"{cmd} {self.duration} s"

        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_sucessfully_started(line)
                self._parse_added_execution_to_queue(line)
            except ParsingDone:
                pass
        return super(Start, self).on_new_line(line, is_full_line)

    # Example line: Test Executor: Successfuly started 'start FDD_FLF18_FZM_1cell_5MHz_TM_Extreme' on 20190109-085940
    _re_successfully_started = re.compile(
        r'(Successfuly|Successfully) started \'start (?P<SCENARIO>.*?)(\.scn)?\' on (?P<QUEUED_TIME>\d+-\d+)')

    def _parse_sucessfully_started(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Start._re_successfully_started, line):
            self.current_ret["SCENARIO"] = self._regex_helper.group("SCENARIO")
            self.current_ret["QUEUED_TIME"] = self._regex_helper.group("QUEUED_TIME")
            raise ParsingDone

    # Example line: Added 'start FDD_FLF18_FZM_1cell_5MHz_TM_Extreme.scn 15 s' execution to queue. Issue 'start' without parameters to start test(s)
    _re_added_execution_to_queue = re.compile(
        r'Added \'start (?P<QUEUED_SCENARIO>.*?)(\.scn)? (?P<DURATION>\d+ \w+)\' execution to queue.'
        r'*Issue \'start\' without parameters to start test')

    def _parse_added_execution_to_queue(self, line):
        """
        Start command.

        :param line: Line from device.
        :return: None but raises ParsingDone if line has information to handle by this method.
        """
        if self._regex_helper.search(Start._re_added_execution_to_queue, line):
            self.current_ret["QUEUED_SCENARIO"] = self._regex_helper.group("QUEUED_SCENARIO")
            self.current_ret["DURATION"] = self._regex_helper.group("DURATION")
            raise ParsingDone


